let user=null,tasks=[],filter='open',editing=null,calDate=new Date(),taskType='task';const $=id=>document.getElementById(id),fmt=d=>d?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00')):'Sin fecha';
