async function loadTasks(){const {data,error}=await sb.from('tasks').select('*,subtasks(id,title,is_done,sort_order),task_updates(id,body,update_type,created_at,author_id),task_emails(id,to_email,cc_email,subject,body,send_status,scheduled_at,sent_at,last_error)').order('created_at',{ascending:false});if(error)return alert(error.message);tasks=data||[];render()}
function visible(t){const today=new Date().toISOString().slice(0,10);if(filter==='open')return t.status!=='done';if(filter==='mine')return t.owner_id===user.id||t.created_by===user.id;if(filter==='waiting')return t.status==='waiting';if(filter==='overdue')return t.status!=='done'&&t.due_date&&t.due_date<today;return true}
