$('newTask').onclick=()=>openTask();function openTask(id){editing=id?tasks.find(t=>t.id===id):null;setType(editing?.task_type||'task');$('modalTitle').textContent=editing?'Editar tarea':'Nueva tarea';$('taskStatusBadge').textContent=editing?labels[editing.status]:'Nueva';$('taskTitle').value=editing?.title||'';$('taskDescription').value=editing?.description||'';$('taskStatus').value=editing?.status||'pending';$('taskPriority').value=editing?.priority||'medium';$('taskDue').value=editing?.due_date||'';$('taskFollow').value=editing?.follow_up_at?editing.follow_up_at.slice(0,16):'';$('taskNext').value=editing?.next_step||'';const e=editing?.task_emails?.[0];$('mailTo').value=e?.to_email||'';$('mailCc').value=e?.cc_email||'';$('mailSubject').value=e?.subject||'';$('mailBody').value=e?.body||'';$('mailSchedule').value=e?.scheduled_at?e.scheduled_at.slice(0,16):'';$('mailStatus').textContent=e?(e.send_status==='sent'?`Enviado ${new Date(e.sent_at).toLocaleString('es-ES')}`:e.send_status==='scheduled'?'Envío programado':'Borrador'):'Guardá la tarea para habilitar envío';$('detailArea').classList.toggle('hidden',!editing);$('deleteTask').classList.toggle('hidden',!editing);$('taskMsg').textContent='';if(editing)renderDetail();$('taskDialog').showModal()}
async function save(close=true){if(!$('taskTitle').value.trim()){ $('taskMsg').textContent='Poné un título.';return null}const payload={title:$('taskTitle').value.trim(),description:$('taskDescription').value.trim(),status:$('taskStatus').value,priority:$('taskPriority').value,due_date:$('taskDue').value||null,follow_up_at:$('taskFollow').value?new Date($('taskFollow').value).toISOString():null,next_step:$('taskNext').value.trim(),task_type:taskType};let data,error;if(editing){({data,error}=await sb.from('tasks').update(payload).eq('id',editing.id).select().single())}else{payload.created_by=user.id;payload.owner_id=user.id;({data,error}=await sb.from('tasks').insert(payload).select().single())}if(error){$('taskMsg').textContent=error.message;return null}if(taskType==='email'){const ep={task_id:data.id,to_email:$('mailTo').value.trim(),cc_email:$('mailCc').value.trim()||null,subject:$('mailSubject').value.trim(),body:$('mailBody').value,created_by:user.id};const {error:ee}=await sb.from('task_emails').upsert(ep,{onConflict:'task_id'});if(ee){$('taskMsg').textContent=ee.message;return null}}editing=data;if(close)$('taskDialog').close();await loadTasks();return data}$('saveTask').onclick=()=>save(true);
