function renderDetail(){const ss=[...(editing.subtasks||[])].sort((a,b)=>a.sort_order-b.sort_order);$('subtasks').innerHTML=ss.map(s=>`<label class="check"><input type="checkbox" data-sub="${s.id}" ${s.is_done?'checked':''}><span>${esc(s.title)}</span></label>`).join('')||'<small>No hay pasos todavía.</small>';document.querySelectorAll('[data-sub]').forEach(c=>c.onchange=async()=>{await sb.from('subtasks').update({is_done:c.checked,completed_at:c.checked?new Date().toISOString():null}).eq('id',c.dataset.sub);await refreshEditing()});const ups=[...(editing.task_updates||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));$('updates').innerHTML=ups.map(u=>`<div class="event"><div>${esc(u.body)}</div><small>${new Date(u.created_at).toLocaleString('es-ES')}</small></div>`).join('')||'<small>Sin actualizaciones todavía.</small>'}
