document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');const cal=b.dataset.view==='calendar';$('tasksView').classList.toggle('hidden',cal);$('filters').classList.toggle('hidden',cal);$('calendarView').classList.toggle('hidden',!cal);$('viewTitle').textContent=cal?'Calendario':'Tareas';renderCalendar()});
function renderCalendar(){const y=calDate.getFullYear(),m=calDate.getMonth();$('monthTitle').textContent=new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(calDate);const first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let out='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),dt=tasks.filter(t=>t.due_date===iso);out+=`<div class="day ${d.getMonth()!==m?'muted':''}"><span class="daynum">${d.getDate()}</span>${dt.map(t=>`<span class="cal-task" data-cal="${t.id}">${t.task_type==='email'?'✉ ':''}${esc(t.title)}</span>`).join('')}</div>`}$('calendar').innerHTML=out;document.querySelectorAll('[data-cal]').forEach(x=>x.onclick=()=>openTask(x.dataset.cal))}$('prevMonth').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()-1,1);renderCalendar()};$('nextMonth').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()+1,1);renderCalendar()};init();